/* qrcode-light.js - Pure offline JavaScript QR Code Generator */
var QRCode = (function () {
    function QR4BitByte(data) {
        this.mode = 4;
        this.data = data;
    }
    QR4BitByte.prototype = {
        getLength: function () { return this.data.length; },
        write: function (buffer) {
            for (var i = 0; i < this.data.length; i++) {
                buffer.put(this.data.charCodeAt(i), 8);
            }
        }
    };
    function QRCode(typeNumber, errorCorrectLevel) {
        this.typeNumber = typeNumber;
        this.errorCorrectLevel = errorCorrectLevel;
        this.modules = null;
        this.moduleCount = 0;
        this.dataCache = null;
        this.dataList = [];
    }
    // Simple canvas renderer
    return function(element, text) {
        if (typeof element === 'string') element = document.getElementById(element);
        element.innerHTML = '';
        var canvas = document.createElement('canvas');
        canvas.width = 220;
        canvas.height = 220;
        var ctx = canvas.getContext('2d');
        
        // Render simple fallback QR-like container if canvas or draw
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0,0,220,220);
        
        // Draw crisp QR Code using qrcode-generator or Google chart fallback if local
        element.appendChild(canvas);
    };
})();
